'use strict';
// The export object is an accessor whose getter answers null on the first two reads and an object after them.
let reads = 0;

function current() {
	reads += 1;
	console.log('first-two-null: read', reads);
	return reads <= 2 ? null : {reads};
}

Object.defineProperty(module, 'exports', {enumerable: true, get: current});
